CommonData.BannerCustomCSS:
@font-face {
    font-family: Knockout Wide;
    src: url(https://cdn.nba.com/next/fonts/KnockoutW05-49Liteweight.woff2) format("woff2"),url(https://cdn.nba.com/next/fonts/KnockoutW05-49Liteweight.woff) format("woff")
}

@import url('https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100..900;1,100..900&display=swap');

#onetrust-consent-sdk #onetrust-policy-title, #onetrust-banner-sdk .ot-dpd-title {
    font-family: 'Knockout 49 Liteweight', "Knockout Wide", sans-serif;
    font-size: 1.5em;
    font-weight: normal;
    line-height: 90%;
    color: #000000;
    text-transform: uppercase;
}

#onetrust-banner-sdk .ot-sdk-container, #onetrust-pc-sdk .ot-sdk-container, #ot-sdk-cookie-policy .ot-sdk-container {
    padding: 50px 20px 0 20px;
}

#onetrust-consent-sdk #onetrust-banner-sdk {
    border-radius: 18px 18px 0 0;
    border: none;
}

#onetrust-consent-sdk #onetrust-policy-text, #onetrust-banner-sdk div  {
    font-family: 'Roboto', sans-serif; 
    color: #696969;
}

#onetrust-consent-sdk #onetrust-policy-text, #onetrust-banner-sdk p:not([role=heading]) {
    line-height: 1.5;
    margin: 5px 0 20px 0
}

#onetrust-banner-sdk .ot-optout-signal {
    font-size: .7em;
    margin-bottom: 20px;
}

/* Button Modifiers */
#onetrust-banner-sdk.ot-iab-2 #onetrust-button-group button {
    border-radius: 5px;
}

#onetrust-consent-sdk #onetrust-accept-btn-handler, #onetrust-banner-sdk #onetrust-reject-all-handler {
    background-color: #000000;
    border-color: #000000;
    color: #FFFFFF;
}

#onetrust-consent-sdk #onetrust-pc-btn-handler, #onetrust-consent-sdk #onetrust-pc-btn-handler.cookie-setting-link {
    color: #000000;
    border-color: #000000;
    background-color: #ffffff;
    text-decoration: none;
    border-style: solid;
    border-width: 1px;
}

#onetrust-banner-sdk.ot-iab-2 .onetrust-vendors-list-handler {
    margin-top: 0;
}

/* Mobile-specific Modifiers */
@media only screen and (max-width: 425px) {
	#onetrust-banner-sdk #onetrust-group-container {
		height:400px;
		overflow-y:auto;
		margin-bottom: 20px;
	}

	::-webkit-scrollbar {
	  width: 6px;
	}
	::-webkit-scrollbar-thumb {
	  background: #eeeeee; 
	  border-radius: 4px;
	}
	#onetrust-consent-sdk #onetrust-banner-sdk {
		height: 650px;
	}

	#onetrust-banner-sdk #onetrust-button-group-parent {
		height: 180px;
		overflow-x: hidden;
	}
    	#onetrust-banner-sdk #onetrust-policy {
        	margin-top: 1em;
                margin-right: .2em;
    	}
}

/* Tablet-specific Modifiers */
@media only screen and (min-width: 426px) and (max-width: 896px) {
    #onetrust-banner-sdk .has-reject-all-button #onetrust-pc-btn-handler.cookie-setting-link {
        padding-left: 0px;
        text-align: center;
    }
}

/* Desktop-specific Modifiers */
@media only screen and (min-width: 1024px) {
    #onetrust-banner-sdk.ot-iab-2 .ot-dpd-title {
        line-height: 90%;
    }
    #onetrust-banner-sdk #onetrust-close-btn-container {
        top: 10%;
    }
}

